  }

  if (response.status === 204) {
    return {};
  }

  return (await response.json()) as TripletexResponse<T>;
}

function norm(value: string | undefined): string {
  return (value ?? "").trim().toLowerCase();
}

function oneExact<T>(items: T[], label: string): T {
  if (items.length !== 1) {
